      if (lastDie > 0) {
        score -= lastDie;
        lastDie = 0;
      }
    } else if (ch == '|') {
      rounds.add(score);
      score = 0;
      lastDie = 0;
      doubleNext = false;
    }
  }

  rounds.add(score);
  return rounds;
}

