    } else if (op == 'UNDO') {
      if (undoLogs[curr].isNotEmpty) {
        String lastOp = undoLogs[curr].removeLast();
        if (lastOp == 'ALLOC') {
          counts[curr]--;
        } else if (lastOp == 'FREE') {
          counts[curr]++;
        }
      }
    } else {
      return false;
    }
  }
  return true;
}

