      return obj ? 'true' : 'false';
    } else if (obj is num) {
      return obj.toString();
    } else if (obj is String) {

      String escaped = obj
          .replaceAll('\\', '\\\\')
          .replaceAll('"', '\\"')
          .replaceAll('\n', '\\n')
          .replaceAll('\r', '\\r')
          .replaceAll('\t', '\\t');
      return '"$escaped"';
    } else if (obj is List) {
