int fn0(List<int> digits) {
  if (digits.length != 13) {
    return -1;
  }

  int checksum = 0;
  for (int i = 0; i < 12; i++) {
    int d = digits[i];
    if (d < 0 || d > 9) {
      return -1;
    }
    if (i % 2 == 0) {
      checksum += d;
    } else {
      checksum += d * 3;
    }
  }

  int checkDigit = digits[12];
  if (checkDigit < 0 || checkDigit > 9) {
    return -1;
  }

  int expected = (10 - (checksum % 10)) % 10;
  if (checkDigit != expected) {
    return -1;
  }

  int primeCount = 0;
  for (int d in digits) {
    if (d == 2 || d == 3 || d == 5 || d == 7) {
      primeCount++;
    }
  }
  return primeCount;
}

