  if (cols == 0) return [];
  List<List<int>> exits = [];
  for (int r = 0; r < rows; r++) {
    for (int c = 0; c < cols; c++) {
      if (grid[r][c] == 'E') exits.add([r, c]);
    }
  }
  if (exits.isEmpty) return [];
  Map<String, int> distances = {};
  List<List<int>> queue = [];
  for (var exit in exits) {
    String key = '${exit[0]},${exit[1]}';
    distances[key] = 0;
    queue.add(exit);
  }
  int head = 0;
  List<List<int>> dirs = [[0, 1], [0, -1], [1, 0], [-1, 0]];
  while (head < queue.length) {
    var curr = queue[head++];
    int r = curr[0], c = curr[1];
    int dist = distances['$r,$c']!;
    for (var dir in dirs) {
      int nr = r + dir[0], nc = c + dir[1];
      if (nr >= 0 && nr < rows && nc >= 0 && nc < cols) {
        String nKey = '$nr,$nc';
        if (!distances.containsKey(nKey)) {
          String cell = grid[nr][nc];
          if (cell == 'A' || cell == 'S') {
            distances[nKey] = dist + 1;
            queue.add([nr, nc]);
          }
        }
      }
    }
  }
  List<List<int>> results = [];
  for (int r = 0; r < rows; r++) {
    for (int c = 0; c < cols; c++) {
      if (grid[r][c] == 'S' && distances.containsKey('$r,$c')) {
        results.add([r, c, distances['$r,$c']!]);
      }
    }
  }
  results.sort((a, b) {
    if (a[2] != b[2]) return a[2].compareTo(b[2]);
    if (a[0] != b[0]) return a[0].compareTo(b[0]);
    return a[1].compareTo(b[1]);
  });
  return results.map((r) => '${r[0]},${r[1]}:${r[2]}').toList();
}

