    sufHi[i] = sufHi[i + 1] + hi[i];
  }
  final List<int> chosen = List<int>.filled(n, 0);
  bool solve(int i, int remaining) {
    if (i == n) return remaining == 0;
    final List<int> options =
        lo[i] == hi[i] ? <int>[lo[i]] : <int>[lo[i], hi[i]];
    for (final int c in options) {
      final int rest = remaining - c;
      if (rest >= sufLo[i + 1] && rest <= sufHi[i + 1]) {
        chosen[i] = c;
        if (solve(i + 1, rest)) return true;
      }
    }
    return false;
  }
  solve(0, totalCents);
  return chosen
      .map((c) => '\$${c ~/ 100}.${(c % 100).toString().padLeft(2, '0')}')
