List<String> fn0(String notation) {
  List<String> splitTopLevel(String s) {
    List<String> parts = [];
    int depth = 0;
    int start = 0;
    for (int i = 0; i < s.length; i++) {
      if (s[i] == '[') {
        depth++;
      } else if (s[i] == ']') {
        depth--;
      } else if (s[i] == ',' && depth == 0) {
        parts.add(s.substring(start, i));
        start = i + 1;
      }
    }
    parts.add(s.substring(start));
    return parts;
  }

  List<String> expandModifiers(String s) {
    String trimmed = s.trim();
    if (trimmed.isEmpty) return [];
    int bracketIdx = trimmed.indexOf('[');
    if (bracketIdx == -1) {
      return [trimmed];
    }
    String name = trimmed.substring(0, bracketIdx);
    int lastBracket = trimmed.lastIndexOf(']');
    String inner = trimmed.substring(bracketIdx + 1, lastBracket);
    List<String> mods = splitTopLevel(inner);
    List<String> results = [];
    for (String mod in mods) {
      List<String> expanded = expandModifiers(mod);
      for (String path in expanded) {
        results.add('$name/$path');
      }
    }
    if (results.isEmpty) {
      return [name];
    }
    return results;
  }

  List<String> results = [];
  if (notation.trim().isEmpty) return results;
  List<String> topItems = splitTopLevel(notation);
  RegExp qtyReg = RegExp(r'^\s*(\d+)x\s+');
  for (String item in topItems) {
    String trimmed = item.trim();
    if (trimmed.isEmpty) continue;
    int qty = 1;
    String rest = trimmed;
    Match? m = qtyReg.firstMatch(trimmed);
    if (m != null) {
      qty = int.parse(m.group(1)!);
      rest = trimmed.substring(m.end);
    }
    if (rest.trim().isEmpty) continue;
    List<String> paths = expandModifiers(rest);
    for (String path in paths) {
      if (qty > 1) {
        results.add('${qty}x $path');
      } else {
        results.add(path);
      }
    }
  }
  return results;
}

