import 'dart:convert';
import 'dart:math';

@pragma('vm:never-inline')
@pragma('vm:entry-point')
void fn0() {

  final graph = <String, List<String>>{
    'A': ['B', 'C'],
    'B': ['C'],
    'C': ['A'],
    'D': ['C'],
  };

  final nodes = graph.keys.toSet().union(graph.values.expand((l) => l).toSet()).toList();
  final n = nodes.length;
  final damping = 0.85;
  final epsilon = 1e-6;
  final maxIterations = 100;

  final nodeIndex = { for (var i = 0; i < nodes.length; i++) nodes[i]: i };

  final outlinks = List.generate(n, (_) => <int>[]);
  final inlinks = List.generate(n, (_) => <int>[]);

  for (var from in graph.keys) {
    var fromIdx = nodeIndex[from]!;
    for (var to in graph[from]!) {
      var toIdx = nodeIndex[to]!;
      outlinks[fromIdx].add(toIdx);
      inlinks[toIdx].add(fromIdx);
    }
  }

  List<double> pr = List.filled(n, 1.0 / n);
  List<double> prNew = List.filled(n, 0.0);

  for (var iter = 0; iter < maxIterations; iter++) {

    double danglingSum = 0.0;
    for (var i = 0; i < n; i++) {
      if (outlinks[i].isEmpty) {
        danglingSum += pr[i];
      }
    }

    for (var i = 0; i < n; i++) {
      prNew[i] = (1.0 - damping) / n;
      prNew[i] += damping * danglingSum / n;
      double sum = 0.0;
      for (var j in inlinks[i]) {
        if (outlinks[j].isNotEmpty) {
