  }

  void deletePreference(String userId, String key) {
    if (userPreferences.containsKey(userId)) {
      userPreferences[userId]!.remove(key);
      print('Deleted: User $userId - $key');
    }
  }

  void clearUserPreferences(String userId) {
    userPreferences.remove(userId);
    print('Cleared all preferences for User $userId');
  }

