      if (runStart == -1) {
        runStart = day;
      }
    } else {
      if (runStart != -1) {
        periods.add(runStart == day - 1 ? "$runStart" : "$runStart-${day - 1}");
        runStart = -1;
      }
    }
  }

  if (runStart != -1) {
    periods.add(runStart == endDay ? "$runStart" : "$runStart-$endDay");
  }

  if (periods.isEmpty) return "Balance healthy";
  return "Overdrawn: days ${periods.join(", ")}";
}

