String fn0(List<int> readings, String gates, int maxSwing) {
  if (readings.length != gates.length) {
    return 'length-mismatch';
  }
  List<String> openMarks = <String>[];
  List<int> openHeights = <int>[];
  int completed = 0;
  int widestSwing = 0;

  for (int i = 0; i < gates.length; i++) {
    String mark = gates[i];
    if (mark == '(' || mark == '[' || mark == '{') {
      openMarks.add(mark);
      openHeights.add(readings[i]);
    } else if (mark == ')' || mark == ']' || mark == '}') {
      if (openMarks.isEmpty) {
        return 'extra-close@$i';
      }
      String open = openMarks.removeLast();
      int startHeight = openHeights.removeLast();
      bool matches = (open == '(' && mark == ')') ||
          (open == '[' && mark == ']') ||
          (open == '{' && mark == '}');
      if (!matches) {
        return 'mismatch@$i';
      }
      int swing = (readings[i] - startHeight).abs();
      if (swing > maxSwing) {
        return 'swing@$i:$swing';
      }
      completed++;
      if (swing > widestSwing) {
        widestSwing = swing;
      }
    } else if (mark != '.') {
      return 'bad-symbol@$i';
    }
  }

  if (openMarks.isNotEmpty) {
    return 'unclosed:${openMarks.length}';
  }
  return 'ok:$completed:$widestSwing';
}

