      String countText = token.substring(1);
      if (countText.startsWith('0')) {
        return false;
      }

      int? count = int.tryParse(countText);
      if (count == null || count <= 0) {
        return false;
      }

      if (color == lastColor) {
        return false;
      }

      moduleCount += count;
      lastColor = color;
    }

    if (moduleCount != size) {
      return false;
    }
  }

  return true;
}

