      if (type == 'DEPOSIT') {
        balances[account] = (balances[account] ?? 0) + amount;
        history.add(op);
      } else if (type == 'WITHDRAW') {
        int current = balances[account] ?? 0;
        if (current >= amount) {
          balances[account] = current - amount;
          history.add(op);
        }
      }
    }
  }
  return balances;
}

