  for (int epoch = 0; epoch < maxEpochs && !trained; epoch++) {
    int correctPredictions = 0;

    print('Epoch ${epoch + 1}:');

    for (int i = 0; i < inputs.length; i++) {

      double x1 = inputs[i][0];
      double x2 = inputs[i][1];
      double target = targets[i];

      double weightedSum = x1 * weight1 + x2 * weight2 + bias;

      double output = weightedSum > 0 ? 1.0 : 0.0;

      double error = target - output;

      if (error != 0) {
        weight1 += learningRate * error * x1;
        weight2 += learningRate * error * x2;
        bias += learningRate * error;

        print('  Input: [${x1.toInt()}, ${x2.toInt()}], Target: ${target.toInt()}, Output: ${output.toInt()}, Error: $error');
