      } else {
        return false;
      }
    } else if (state == 2) {
      if (cmd == "NEXT") {
        state = 1;
      } else if (cmd == "PREV") {
        if (isShuffle) return false;
        state = 1;
      } else if (cmd == "SHUFFLE_ON") {
