  }

  List<int> dp = List.filled(n, 0);
  List<int> prev = List.filled(n, -1);

  for (int i = 0; i < n; i++) {
    dp[i] = 1;
    prev[i] = -1;

    for (int j = 0; j < i; j++) {
      if (requests[i] - requests[j] <= maxGap) {
        if (dp[j] + 1 > dp[i]) {
          dp[i] = dp[j] + 1;
          prev[i] = j;
        }
      }
    }
  }

