  int bestEnd = -1;

  for (int i = 0; i < n; i++) {
    if (dp[i] > maxLen) {
      maxLen = dp[i];
      bestEnd = i;
    }
  }

  int current = bestEnd;
  while (current != -1) {
    result.add(requests[current]);
    current = prev[current];
  }

  return result.reversed.toList();
}

