List<String> fn0(List<int> amountsCents, int targetSumCents) {
  if (amountsCents.isEmpty) {
    return targetSumCents == 0 ? [""] : [];
  }
  List<String> results = [];
  int n = amountsCents.length;
  List<int> minSuffix = List.filled(n + 1, 0);
  List<int> maxSuffix = List.filled(n + 1, 0);
  for (int i = n - 1; i >= 0; i--) {
    int amount = amountsCents[i];
    int floorVal = (amount ~/ 10) * 10;
    int ceilVal = ((amount + 9) ~/ 10) * 10;
    minSuffix[i] = minSuffix[i + 1] + floorVal;
    maxSuffix[i] = maxSuffix[i + 1] + ceilVal;
  }
  void backtrack(int index, int currentSum, List<int> currentCombo) {
    if (currentSum + minSuffix[index] > targetSumCents) return;
    if (currentSum + maxSuffix[index] < targetSumCents) return;
    if (index == n) {
      if (currentSum == targetSumCents) {
        results.add(currentCombo.join(','));
      }
      return;
    }
    int amount = amountsCents[index];
    int floorVal = (amount ~/ 10) * 10;
    int ceilVal = ((amount + 9) ~/ 10) * 10;
    List<int> options = floorVal == ceilVal ? [floorVal] : [floorVal, ceilVal];
    for (int opt in options) {
      currentCombo.add(opt);
      backtrack(index + 1, currentSum + opt, currentCombo);
      currentCombo.removeLast();
    }
  }
  backtrack(0, 0, []);
  results.sort();
  return results;
}

