void fn0() {

  Map<String, String> formData = {
    'username': 'john_doe',
    'email': 'john.doe@example.com',
    'password': 'Pass123!',
    'confirmPassword': 'Pass123!',
    'age': '25',
    'phone': '+1-555-123-4567',
    'website': 'https://example.com',
    'zipCode': '12345'
  };

  Map<String, List<bool Function(String)>> validationRules = {
    'username': [
      (value) => value.isNotEmpty,
      (value) => value.length >= 3,
      (value) => value.length <= 20,
      (value) => RegExp(r'^[a-zA-Z0-9_]+$').hasMatch(value),
    ],
    'email': [
      (value) => value.isNotEmpty,
      (value) => RegExp(r'^[\w-\.]+@([\w-]+\.)+[\w-]{2,4}$').hasMatch(value),
    ],
    'password': [
      (value) => value.isNotEmpty,
      (value) => value.length >= 8,
      (value) => RegExp(r'[A-Z]').hasMatch(value),
      (value) => RegExp(r'[a-z]').hasMatch(value),
      (value) => RegExp(r'[0-9]').hasMatch(value),
      (value) => RegExp(r'[!@#$%^&*(),.?":{}|<>]').hasMatch(value),
    ],
    'confirmPassword': [
      (value) => value.isNotEmpty,
      (value) => value == formData['password'],
    ],
    'age': [
      (value) => value.isNotEmpty,
      (value) => int.tryParse(value) != null,
      (value) => int.tryParse(value) != null && int.parse(value) >= 18,
      (value) => int.tryParse(value) != null && int.parse(value) <= 120,
    ],
    'phone': [
      (value) => value.isNotEmpty,
      (value) => RegExp(r'^\+?[\d\s\-\(\)]+$').hasMatch(value),
      (value) => value.replaceAll(RegExp(r'[^\d]'), '').length >= 10,
    ],
    'website': [
      (value) => value.isEmpty || RegExp(r'^https?://[\w\-]+(\.[\w\-]+)+[/#?]?.*$').hasMatch(value),
    ],
    'zipCode': [
      (value) => value.isNotEmpty,
      (value) => RegExp(r'^\d{5}(-\d{4})?$').hasMatch(value),
    ],
  };

  Map<String, List<String>> errorMessages = {
    'username': [
      'Username is required',
      'Username must be at least 3 characters',
      'Username must not exceed 20 characters',
      'Username can only contain letters, numbers, and underscores',
    ],
    'email': [
      'Email is required',
      'Please enter a valid email address',
    ],
    'password': [
      'Password is required',
      'Password must be at least 8 characters',
      'Password must contain at least one uppercase letter',
      'Password must contain at least one lowercase letter',
      'Password must contain at least one number',
      'Password must contain at least one special character',
    ],
    'confirmPassword': [
      'Please confirm your password',
      'Passwords do not match',
    ],
    'age': [
      'Age is required',
      'Please enter a valid number',
      'You must be at least 18 years old',
      'Please enter a valid age',
    ],
    'phone': [
      'Phone number is required',
      'Please enter a valid phone number',
      'Phone number must be at least 10 digits',
    ],
    'website': [
      'Please enter a valid URL (starting with http:// or https://)',
    ],
    'zipCode': [
      'Zip code is required',
      'Please enter a valid zip code (e.g., 12345 or 12345-6789)',
    ],
  };

  Map<String, List<String>> validateForm(Map<String, String> data) {
    Map<String, List<String>> errors = {};

    validationRules.forEach((field, rules) {
      String value = data[field] ?? '';
      List<String> fieldErrors = [];

      for (int i = 0; i < rules.length; i++) {
        if (!rules[i](value)) {
          fieldErrors.add(errorMessages[field]![i]);
        }
      }

      if (fieldErrors.isNotEmpty) {
        errors[field] = fieldErrors;
      }
    });

    return errors;
  }

  void displayValidationResults(Map<String, String> data, Map<String, List<String>> errors) {
    print('=' * 60);
    print('FORM VALIDATION RESULTS');
    print('=' * 60);

    if (errors.isEmpty) {
      print('\n✅ Form is valid! All fields passed validation.\n');
      print('Submitted Data:');
      print('-' * 40);
      data.forEach((key, value) {
        if (key == 'password' || key == 'confirmPassword') {
          print('$key: ${value.replaceAll(RegExp(r'.'), '*')}');
        } else {
          print('$key: $value');
        }
      });
    } else {
      print('\n❌ Form validation failed!\n');
      print('Errors found:');
      print('-' * 40);
      errors.forEach((field, fieldErrors) {
        print('\n📋 $field:');
        for (String error in fieldErrors) {
          print('   • $error');
        }
      });

      print('\n\nValid fields:');
      print('-' * 40);
      data.forEach((key, value) {
        if (!errors.containsKey(key)) {
          if (key == 'password' || key == 'confirmPassword') {
            print('✓ $key: ${value.replaceAll(RegExp(r'.'), '*')}');
          } else {
            print('✓ $key: $value');
          }
        }
      });
    }
    print('\n' + '=' * 60);
  }

  print('\nTEST 1: Valid Form Data');
  Map<String, List<String>> validationErrors = validateForm(formData);
  displayValidationResults(formData, validationErrors);

  Map<String, String> invalidFormData = {
    'username': 'jo',  
    'email': 'invalid-email',  
    'password': 'weak',  
    'confirmPassword': 'different',  
    'age': '16',  
    'phone': '123',  
    'website': 'not-a-url',  
    'zipCode': 'ABC123'  
  };

  print('\n\nTEST 2: Invalid Form Data');
  validationErrors = validateForm(invalidFormData);
  displayValidationResults(invalidFormData, validationErrors);

  Map<String, String> partialFormData = {
    'username': 'valid_user123',
    'email': 'valid@email.com',
    'password': 'weak',  
    'confirmPassword': 'weak',
    'age': '30',
    'phone': '',  
    'website': 'https://valid-site.com',
    'zipCode': '12345-6789'
  };

  print('\n\nTEST 3: Partially Valid Form Data');
  validationErrors = validateForm(partialFormData);
  displayValidationResults(partialFormData, validationErrors);

  print('\n\nREAL-TIME VALIDATION SIMULATION');
  print('=' * 60);

  String passwordInput = '';
  List<String> passwordSteps = ['P', 'Pa', 'Pas', 'Pass', 'Pass1', 'Pass12', 'Pass123', 'Pass123!'];

  print('Simulating password input:');
  for (String step in passwordSteps) {
    passwordInput = step;
    List<String> errors = [];

    for (int i = 0; i < validationRules['password']!.length; i++) {
      if (!validationRules['password']![i](passwordInput)) {
        errors.add(errorMessages['password']![i]);
      }
    }

    print('\nInput: "$passwordInput"');
    if (errors.isEmpty) {
      print('✅ Valid password!');
    } else {
      print('❌ Issues:');
      for (String error in errors) {
        print('   • $error');
      }
    }
  }

  print('\n' + '=' * 60);
}

