double fn0(int startFloor, List<int> requests, int windowSize) {
  int n = requests.length;
  if (windowSize <= 0 || n < windowSize) {
    return 0.0;
  }

  List<int> minIdx = [];
  List<int> maxIdx = [];
  double best = double.infinity;

  for (int i = 0; i < n; i++) {
    while (minIdx.isNotEmpty && requests[minIdx.last] >= requests[i]) {
      minIdx.removeLast();
    }
    minIdx.add(i);

    while (maxIdx.isNotEmpty && requests[maxIdx.last] <= requests[i]) {
      maxIdx.removeLast();
    }
    maxIdx.add(i);

    if (minIdx.first <= i - windowSize) {
      minIdx.removeAt(0);
    }
    if (maxIdx.first <= i - windowSize) {
      maxIdx.removeAt(0);
    }

    if (i >= windowSize - 1) {
      int minFloor = requests[minIdx.first];
      int maxFloor = requests[maxIdx.first];
      double total;

      if (minFloor >= startFloor) {
        total = (maxFloor - startFloor).toDouble();
      } else if (maxFloor < startFloor) {
        total = (startFloor - minFloor).toDouble();
      } else {
        double upFirst = (2 * maxFloor - startFloor - minFloor).toDouble();
        double downFirst = (startFloor + maxFloor - 2 * minFloor).toDouble();
        total = upFirst < downFirst ? upFirst : downFirst;
      }

      double avg = total / windowSize;
      if (avg < best) {
        best = avg;
      }
    }
  }

  return best;
}

