Map<String, int> fn0(String password) {
  int digits = 0, uppercase = 0, lowercase = 0, special = 0;
  List<String> stack = <String>[];
  bool valid = true;
  const open = '<([';
  const close = '>)]';
  const pairs = {'<': '>', '(': ')', '[': ']'};
  for (int i = 0; i < password.length; i++) {
    String c = password[i];
    if (c.codeUnitAt(0) >= 48 && c.codeUnitAt(0) <= 57) {
      digits++;
    } else if (c.codeUnitAt(0) >= 65 && c.codeUnitAt(0) <= 90) {
      uppercase++;
    } else if (c.codeUnitAt(0) >= 97 && c.codeUnitAt(0) <= 122) {
      lowercase++;
    } else {
      special++;
    }
    if (open.contains(c)) {
      stack.add(c);
    } else if (close.contains(c)) {
      if (stack.isEmpty) {
        valid = false;
      } else {
        String last = stack.removeLast();
        if (pairs[last] != c) valid = false;
      }
    }
  }
  if (stack.isNotEmpty) valid = false;
  return {
    'digits': digits,
    'uppercase': uppercase,
    'lowercase': lowercase,
    'special': special,
    'validBrackets': valid ? 1 : 0,
  };
}

